    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Bound v to a reasonable value (e.g., in [0, 1e6]) to avoid unrealistic fuzz
        uint256 boundedV = bound(v, 0, 1e6);
        // Record whether the call reverts
        bool reverted;
        try c.transfer(from, caddress, _tos, boundedV) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The property: if _tos is empty, the call must revert; otherwise it must not revert
        assertTrue((_tos.length == 0) ? reverted : !reverted);
    }
